import{_ as o,c as t,a as i,o as a}from"./app-C_dHcy8Q.js";const s={};function l(u,e){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="ui-schema-views-web" tabindex="-1"><a class="header-anchor" href="#ui-schema-views-web"><span>UI Schema &amp; Views (Web)</span></a></h1><p>This document explains how the Web app renders forms (UI Schema) and output views from packs.</p><p>UI Schema</p><ul><li>Source: <code>ui/&lt;function_id&gt;.schema.json</code> (JSON Schema), <code>ui/&lt;function_id&gt;.uischema.json</code> (UI Schema)</li><li>Layout (optional): <ul><li><code>ui:layout</code>: <code>{ &quot;type&quot;: &quot;grid&quot;, &quot;cols&quot;: 1|2|3|4 }</code> (default 1)</li><li><code>ui:groups</code>: <code>[ { &quot;title&quot;: &quot;Group Name&quot;, &quot;fields&quot;: [&quot;field1&quot;,&quot;field2&quot;,...] }, ... ]</code></li></ul></li><li>Field UI hints (<code>ui:fields</code> per field): <ul><li><code>label</code>, <code>placeholder</code>, <code>widget</code> (input/textarea/select)</li><li><code>enum</code> and <code>x-enum-labels</code> available for select rendering</li><li><code>show_if</code> / <code>required_if</code>: simple expressions using paths and operators <code>==</code>, <code>!=</code>, <code>&amp;&amp;</code>, <code>||</code>. Example: <code>$.type == &quot;advanced&quot; &amp;&amp; $.enabled == true</code></li></ul></li><li>Supported types: <ul><li><code>string</code> / <code>number</code> / <code>integer</code> / <code>boolean</code></li><li><code>array</code> (adds/removes items)</li><li><code>object</code> with <code>properties</code> (nested group)</li><li><code>object</code> with <code>additionalProperties</code> (map) – UI as key/value entries, submitted as JSON object</li></ul></li><li>Validation: <ul><li><code>minLength</code> / <code>maxLength</code> / <code>pattern</code> for strings</li><li><code>minimum</code> / <code>maximum</code> for numbers</li></ul></li></ul><p>Views &amp; Transform</p><ul><li>Descriptor: <code>outputs.views[]</code> can specify <code>renderer</code>, optional <code>transform</code></li><li>Transform (frontend, safe subset): <ul><li>When <code>lang</code> is <code>cel</code> (or omitted), expression is treated as a JSON path starting at root (e.g., <code>$.data.series</code>)</li><li>The selected value is passed to the renderer component</li><li>Path supports simple array indexing via brackets, e.g., <code>$.value[1]</code>.</li></ul></li><li>Built-in renderers: <ul><li><code>json.view</code> – pretty-print JSON</li><li><code>table.basic</code> – render array of objects as a table</li><li><code>echarts.line</code> – line chart via ECharts (loaded on demand from CDN). Data accepts Prometheus matrix via <code>$.data.result</code> or generic <code>{ series: [...] }</code>/<code>[{ name, data: [[ms,value],...] }]</code>; options are passed through.</li></ul></li></ul><p>Layout</p><ul><li>Use <code>outputs.layout</code> to control multiple views arrangement.</li><li>Example: <code>{ &quot;type&quot;: &quot;grid&quot;, &quot;cols&quot;: 2 }</code> renders views in a responsive two-column grid.</li></ul><p>Transform Templates (JSON-based)</p><ul><li>Besides <code>expr</code>, packs can provide <code>transform.template</code> to declaratively reshape data.</li><li>Template strings starting with <code>$.</code> are resolved as JSON paths against the current context item; strings starting with <code>$$.</code> resolve against the original root.</li><li>Special form: <code>{ &quot;forEach&quot;: { &quot;path&quot;: &quot;$.items&quot;, &quot;template&quot;: { ... } } }</code> maps arrays.</li><li>Optional filtering: <code>{ &quot;forEach&quot;: { &quot;path&quot;: &quot;$.items&quot;, &quot;where&quot;: { &quot;contains&quot;: [&quot;$.name&quot;, &quot;prod&quot;] }, &quot;template&quot;: { ... } } }</code>.</li><li>Aliases &amp; helpers: <ul><li><code>map</code>: <code>{ &quot;map&quot;: { &quot;path&quot;: &quot;$.items&quot;, &quot;template&quot;: { ... } } }</code></li><li><code>pluck</code>: <code>{ &quot;pluck&quot;: { &quot;path&quot;: &quot;$.items&quot;, &quot;value&quot;: &quot;$.field&quot; } }</code></li><li>Aggregates: <code>sum</code> / <code>avg</code> on arrays of values: <code>{ &quot;sum&quot;: { &quot;path&quot;: &quot;$.items&quot;, &quot;value&quot;: &quot;$.v&quot; } }</code></li><li>Value directives: wrap values to coerce/compute <ul><li><code>{ &quot;number&quot;: &quot;$.v&quot; }</code> → Number($.v)</li><li><code>{ &quot;msFromSec&quot;: &quot;$.ts&quot; }</code> → seconds to milliseconds</li><li><code>{ &quot;mul&quot;: { &quot;value&quot;: &quot;$.v&quot;, &quot;by&quot;: 100 } }</code>, <code>{ &quot;div&quot;: { &quot;value&quot;: &quot;$.v&quot;, &quot;by&quot;: 1000 } }</code></li><li><code>{ &quot;add&quot;: { &quot;a&quot;: &quot;$.a&quot;, &quot;b&quot;: 1 } }</code>, <code>{ &quot;sub&quot;: { &quot;a&quot;: &quot;$.a&quot;, &quot;b&quot;: 1 } }</code></li><li><code>{ &quot;toFixed&quot;: { &quot;value&quot;: &quot;$.v&quot;, &quot;digits&quot;: 2 } }</code> → Number fixed decimals</li><li><code>{ &quot;isoFromMs&quot;: &quot;$.tsMs&quot; }</code>, <code>{ &quot;isoFromSec&quot;: &quot;$.tsSec&quot; }</code> → ISO datetime string</li></ul></li></ul></li></ul><p>View Conditions</p><ul><li>Optional <code>show_if</code> on a view allows hiding the view when the referenced path is falsy or an empty array.</li><li>Example: <code>{ &quot;id&quot;: &quot;table&quot;, &quot;show_if&quot;: &quot;$.data.items&quot;, ... }</code>.</li><li>Example (Prometheus matrix → ECharts series):</li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">{</span>
<span class="line">  &quot;views&quot;: [</span>
<span class="line">    {</span>
<span class="line">      &quot;id&quot;: &quot;chart&quot;,</span>
<span class="line">      &quot;renderer&quot;: &quot;echarts.line&quot;,</span>
<span class="line">      &quot;transform&quot;: {</span>
<span class="line">        &quot;template&quot;: {</span>
<span class="line">          &quot;forEach&quot;: {</span>
<span class="line">            &quot;path&quot;: &quot;$.data.result&quot;,</span>
<span class="line">            &quot;template&quot;: { &quot;name&quot;: &quot;$.metric.instance&quot;, &quot;data&quot;: &quot;$.values&quot; }</span>
<span class="line">          }</span>
<span class="line">        }</span>
<span class="line">      }</span>
<span class="line">    }</span>
<span class="line">  ]</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Notes</p><ul><li>This is a minimal baseline intended for quick PoC. Full CEL transforms and richer Schema-Form are planned.</li><li>Packs generated by <code>protoc-gen-croupier</code> include a default UI Schema with a grid layout and inferred groups.</li></ul><p>Plugins</p><ul><li>Built-in renderers are registered in <code>web/src/plugin/registry.ts</code>.</li><li>Packs can ship frontend plugins under <code>web-plugin/*</code> and reference them in <code>manifest.json</code> via <code>web_plugins</code>.</li><li>The plugin module must export a default function receiving <code>{ registerRenderer }</code> and may register custom renderers.</li><li>Example (Prom pack): <code>web-plugin/echarts_plugin.js</code> registers <code>echarts.bar</code> and is listed in <code>manifest.json</code> → <code>web_plugins</code>.</li></ul>`,17)])])}const d=o(s,[["render",l]]),n=JSON.parse('{"path":"/ui-and-views.html","title":"UI Schema & Views (Web)","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1763325744000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":2,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"0ac3783c0cafbb7e76dd3fb0484cad90c77386b8","time":1763325744000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(analytics): fix unresolved links; add missing pages; harden MDX; CI link check\\\\n\\\\nfeat(analytics): add public ingestion service (cmd/analytics-ingest), Makefile targets, Dockerfiles; compose service; fix worker image\\\\n\\\\nchore(docs): adjust config to ignore node_modules in docs plugin; remove duplicate index page\\\\n\\\\nrefactor(docs): escape MDX-sensitive chars and fence YAML blocks"},{"hash":"228147054e4f1a15cada6bb3a8af42c4128040fb","time":1762002341000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"chore: commit local changes"}]},"filePathRelative":"ui-and-views.md"}');export{d as comp,n as data};
